$ErrorActionPreference='Stop'
$js=@'
const v=await(await fetch("http://127.0.0.1:17410/json/version")).json();
const ws=new WebSocket(v.webSocketDebuggerUrl);
await new Promise((yes,no)=>{ws.addEventListener("open",yes,{once:true});ws.addEventListener("error",no,{once:true})});
ws.addEventListener("message",e=>{let x=JSON.parse(e.data);if(x.id===1){console.log(JSON.stringify({target_id:x.result?.targetId||null,error:x.error?.code||null}));ws.close();process.exit(0)}});
ws.send(JSON.stringify({id:1,method:"Target.createTarget",params:{url:"https://krasnoyarsk.cian.ru/rent/suburban/292108973/",background:true,newWindow:false}}));
setTimeout(()=>process.exit(1),5500)
'@
$p=Join-Path $env:TEMP 'pc-cian-kru-mcp.mjs'
try{[System.IO.File]::WriteAllText($p,$js,[System.Text.UTF8Encoding]::new($false));& node.exe $p}finally{Remove-Item -LiteralPath $p -Force -ErrorAction SilentlyContinue}
